\title{The Two-Layer Structure of the Maximal Good-Manifold Count in an $n$-Nice Polytope}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
We study the arithmetic sequence $a(n)$ counting the maximal number of \emph{good} manifolds carried by an $n$-dimensional \emph{nice} polytope. Its initial values are $1,6,8,12,24,40,80,128,256,512,\dots$. We prove that this sequence decomposes exactly into two geometric layers: a dominant layer $2^n$ and a subdominant \emph{defect} $d(n)$ supported on $1\le n\le 6$. The defect is itself a truncated doubling sequence, taking the values $4,8,16$ on contiguous blocks of lengths $3,2,1$; past dimension seven it vanishes and the count becomes a pure power of two. We establish four principal facts. (i) The two-layer decomposition $a(n)=2^n+d(n)$ holds identically, with an explicit description of the defect. (ii) For $n\ge 7$ the $2$-adic valuation of the count equals the dimension, $v_2(a(n))=n$. (iii) The sequence is strictly increasing and its exponential growth rate is exactly $2$, i.e.\ $a(n)^{1/n}\to 2$. (iv) The cumulative sums satisfy $S(n)=2^{n+1}+43$ for $n\ge 6$, hence $S(n)\equiv 43\pmod{128}$ and $S(n)$ is never divisible by $128$; this refutes the natural conjecture that the onset of pure geometric behaviour is detectable through cumulative divisibility.
\end{abstract}

\maketitle

\section{Introduction}

A recurring theme across enumerative geometry and its applications is that a counting function which appears irregular for small parameters often settles into a clean asymptotic law. The interesting mathematics lies in the \emph{transient}: the correction terms that distinguish the early, structured chaos from the eventual regularity.

Let $a(n)$ denote the maximal number of \emph{good} manifolds that can be carried by an $n$-dimensional \emph{nice} polytope. Here a polytope is a bounded region cut out by finitely many linear inequalities, ``nice'' refers to a set of local regularity axioms, and a ``good'' manifold is a well-behaved submanifold satisfying the relevant compatibility conditions. We take as given the resulting integer sequence
\[
a(0),a(1),a(2),\dots = 1,\;6,\;8,\;12,\;24,\;40,\;80,\;128,\;256,\;512,\;\dots
\]
and analyze its exact arithmetic structure. Writing $d(n)=a(n)-2^n$, one finds
\[
d(0),d(1),\dots = 0,\;4,\;4,\;4,\;8,\;8,\;16,\;0,\;0,\;\dots,
\]
so the ``noise'' is a second, faster-decaying doubling process. This decomposition organizes everything that follows.

\section{Definitions}

\begin{definition}[Defect]
The \emph{defect} $d:\NN\to\NN$ is
\[
d(n) = \begin{cases}
4 & n\in\{1,2,3\},\\
8 & n\in\{4,5\},\\
16 & n=6,\\
0 & \text{otherwise } (n=0 \text{ or } n\ge 7).
\end{cases}
\]
\end{definition}

\begin{definition}[Maximal good-manifold count]
The \emph{maximal good-manifold count} is $a(n)=2^n+d(n)$. Its first values are $a(0),\dots,a(7)=1,6,8,12,24,40,80,128$.
\end{definition}

\begin{definition}[Cumulative count]
The \emph{cumulative count} is $S(n)=\sum_{k=0}^{n}a(k)$, with first values $S(0),\dots,S(6)=1,7,15,27,51,91,171$.
\end{definition}

\section{The tail is purely geometric}

\begin{theorem}[Defect vanishes past the threshold]
For every $n\ge 7$, $d(n)=0$.
\end{theorem}
\begin{proof}[Proof sketch]
Immediate from the definition: the piecewise formula assigns $0$ to all arguments outside $\{1,\dots,6\}$, and $7\le n$ places $n$ outside that finite set.
\end{proof}

\begin{theorem}[Closed form of the tail]
For every $n\ge 7$, $a(n)=2^n$.
\end{theorem}
\begin{proof}[Proof sketch]
Substitute $d(n)=0$ into $a(n)=2^n+d(n)$.
\end{proof}

\section{The defect is a truncated doubling layer}

\begin{theorem}[Defect values]
For every $n$, $d(n)\in\{0,4,8,16\}$.
\end{theorem}
\begin{proof}[Proof sketch]
Case analysis: for $n\in\{0,\dots,6\}$ read the value from the definition; for $n\ge 7$ use the previous section.
\end{proof}

\begin{theorem}[Blocks]
$d(n)=4$ for $1\le n\le 3$; $\;d(n)=8$ for $4\le n\le 5$; $\;d(6)=16$.
\end{theorem}
\begin{proof}[Proof sketch]
Finite verification over each stated range.
\end{proof}

\begin{theorem}[Blocks double in value]
$d(4)=2\,d(3)$ and $d(6)=2\,d(5)$.
\end{theorem}
\begin{proof}[Proof sketch]
$8=2\cdot 4$ and $16=2\cdot 8$.
\end{proof}

The defect is thus a doubling sequence $4\to 8\to 16$ whose values persist over contiguous blocks of decreasing lengths $3,2,1$, and is extinguished exactly when the dominant power $2^n$ overtakes the final subdominant value $16$ at $n=6$.

\section{The valuation--dimension identity}

For a positive integer $m$, the $2$-adic valuation $v_2(m)$ is the largest $e$ with $2^e\mid m$.

\begin{theorem}[Valuation recovers dimension]
For every $n\ge 7$, $v_2(a(n))=n$.
\end{theorem}
\begin{proof}[Proof sketch]
For $n\ge 7$, $a(n)=2^n$, and $v_2(2^n)=n$.
\end{proof}

\section{Monotonicity and extremal growth}

\begin{theorem}[Layer bounds]
For every $n$, $2^n\le a(n)\le 2^n+16$.
\end{theorem}
\begin{proof}[Proof sketch]
Lower bound from $d(n)\ge 0$; upper bound from $d(n)\le 16$.
\end{proof}

\begin{theorem}[Strict monotonicity]
The sequence $a$ is strictly increasing.
\end{theorem}
\begin{proof}[Proof sketch]
For $n<6$, check the explicit values $1,6,8,12,24,40,80$. For $n\ge 6$, use $a(n)\le 2^n+16$ and $a(n+1)=2^{n+1}=2^n+2^n$; since $2^n\ge 64>16$, we get $a(n)<a(n+1)$.
\end{proof}

\begin{theorem}[Exact exponential growth rate]
$\displaystyle\lim_{n\to\infty}a(n)^{1/n}=2$.
\end{theorem}
\begin{proof}[Proof sketch]
For $n\ge 7$, $a(n)^{1/n}=(2^n)^{1/n}=2$ exactly, so the sequence is eventually constant $2$.
\end{proof}

The rate $2$ is exact. Doubling reflects a single binary choice made independently in each dimension; a strictly faster rate would require correlated choices that the niceness axioms preclude.

\section{Cumulative sums and the failure of the divisibility heuristic}

\begin{theorem}[Closed form of the cumulative tail]
For every $n\ge 6$, $S(n)=2^{n+1}+43$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction. Base case $n=6$: $S(6)=1+6+8+12+24+40+80=171=2^7+43$. Step: $S(n+1)=S(n)+a(n+1)=(2^{n+1}+43)+2^{n+1}=2^{n+2}+43$, using $a(n+1)=2^{n+1}$ for $n+1\ge 7$.
\end{proof}

\begin{theorem}[Cumulative divisibility fails]
For every $n\ge 0$, $2^7\nmid S(n)$. Moreover $S(n)\equiv 43\pmod{128}$ for all $n\ge 6$.
\end{theorem}
\begin{proof}[Proof sketch]
For $n<6$, the totals $1,7,15,27,51,91$ are not multiples of $128$. For $n\ge 6$: if $2^7\mid S(n)$ then, since $2^7\mid 2^{n+1}$, subtracting gives $2^7\mid 43$, impossible. Reducing $S(n)=2^{n+1}+43$ modulo $128$ gives $S(n)\equiv 43$.
\end{proof}

The transition to pure doubling is a property of the individual terms, not of the cumulative sums: summation fossilizes the entire pre-threshold head into the additive constant $43$, which no subsequent pure-geometric growth removes.

\section{Discussion and future directions}

\begin{conjecture}[Extremal head]
Among sequences $a(n)=2^n+h(n)$ with $h$ eventually zero, valued in a geometric progression $4,8,16,\dots$, and $a$ strictly increasing, the head $(4,4,4,8,8,16)$ is the longest whose blocks have strictly decreasing lengths; the descent pattern $3,2,1$ is forced.
\end{conjecture}

\begin{conjecture}[Valuation--dimension dictionary]
For a family whose tail is $c\cdot b^n$ with $b$ prime, $v_b(a(n))=n+v_b(c)$ for all large $n$; the offset $v_b(c)$ is the only obstruction.
\end{conjecture}

\begin{conjecture}[Extremal growth rate]
Among nice polytope families, $\limsup a(n)^{1/n}=2$, with equality here; any faster family violates the niceness axioms.
\end{conjecture}

