"""Demo 1: The two-layer decomposition a(n) = 2^n + d(n)."""
from __future__ import annotations


def defect(n: int) -> int:
    """Defect d(n): the excess of a(n) over the dominant layer 2^n."""
    return {1: 4, 2: 4, 3: 4, 4: 8, 5: 8, 6: 16}.get(n, 0)


def a(n: int) -> int:
    """Maximal good-manifold count in an n-nice polytope."""
    return 2 ** n + defect(n)


def show(upper: int = 10) -> None:
    for n in range(upper):
        assert a(n) == 2 ** n + defect(n)
        print(f"a({n}) = 2^{n} + d({n}) = {2**n} + {defect(n)} = {a(n)}")


if __name__ == "__main__":
    show()

"""Demo 2: The 2-adic valuation recovers the dimension for n >= 7."""
from __future__ import annotations


def a(n: int) -> int:
    return 2 ** n + {1: 4, 2: 4, 3: 4, 4: 8, 5: 8, 6: 16}.get(n, 0)


def v2(m: int) -> int:
    """2-adic valuation: largest e with 2^e | m."""
    e = 0
    while m % 2 == 0:
        m //= 2
        e += 1
    return e


def check(upper: int = 40) -> None:
    for n in range(7, upper):
        assert v2(a(n)) == n, (n, v2(a(n)))
        print(f"v2(a({n})) = v2({a(n)}) = {v2(a(n))} = {n}")
    print(f"Verified v2(a(n)) == n for 7 <= n < {upper}")


if __name__ == "__main__":
    check()

"""Demo 3: Cumulative closed form S(n)=2^(n+1)+43 and the 43 mod 128 residue."""
from __future__ import annotations


def a(n: int) -> int:
    return 2 ** n + {1: 4, 2: 4, 3: 4, 4: 8, 5: 8, 6: 16}.get(n, 0)


def S(n: int) -> int:
    return sum(a(k) for k in range(n + 1))


def check(upper: int = 40) -> None:
    for n in range(6, upper):
        assert S(n) == 2 ** (n + 1) + 43
        assert S(n) % 128 == 43
        assert S(n) % 128 != 0
    print(f"S(n) = 2^(n+1)+43 and S(n) = 43 (mod 128) verified for 6 <= n < {upper}")
    print("Running totals mod 128:",
          [S(n) % 128 for n in range(10)])


if __name__ == "__main__":
    check()

"""Demo 4: The exact exponential growth rate a(n)^(1/n) -> 2."""
from __future__ import annotations


def a(n: int) -> int:
    return 2 ** n + {1: 4, 2: 4, 3: 4, 4: 8, 5: 8, 6: 16}.get(n, 0)


def growth(upper: int = 100) -> None:
    for n in range(1, upper):
        root = a(n) ** (1.0 / n)
        flag = " (exact = 2)" if n >= 7 else ""
        if n <= 8 or n % 20 == 0:
            print(f"n={n:>3}: a(n)^(1/n) = {root:.10f}{flag}")


if __name__ == "__main__":
    growth()

