from __future__ import annotations
from typing import List, Tuple


def defect(n: int) -> int:
    """Defect layer d(n) in O(1)."""
    return {1: 4, 2: 4, 3: 4, 4: 8, 5: 8, 6: 16}.get(n, 0)


def good_manifold_count(n: int) -> int:
    """Maximal good-manifold count a(n) = 2^n + d(n) in O(n) (from the shift)."""
    return (1 << n) + defect(n)


def decompose(n: int) -> Tuple[int, int, int]:
    """Return (a(n), dominant 2^n, defect d(n))."""
    dom = 1 << n
    return dom + defect(n), dom, defect(n)


def table(upper: int) -> List[Tuple[int, int, int]]:
    """Table of decompositions for 0 <= n < upper."""
    return [decompose(n) for n in range(upper)]

from __future__ import annotations


def good_manifold_count(n: int) -> int:
    return (1 << n) + {1: 4, 2: 4, 3: 4, 4: 8, 5: 8, 6: 16}.get(n, 0)


def two_adic_valuation(m: int) -> int:
    """Largest e with 2^e | m, computed by trailing-zero peeling in O(v2(m))."""
    if m <= 0:
        raise ValueError("positive integer required")
    e = 0
    while m & 1 == 0:
        m >>= 1
        e += 1
    return e


def recover_dimension(n: int) -> int:
    """For n >= 7, recover the dimension from the count alone via valuation."""
    return two_adic_valuation(good_manifold_count(n))

