from __future__ import annotations
from typing import Tuple


def good_manifold_count(n: int) -> int:
    return (1 << n) + {1: 4, 2: 4, 3: 4, 4: 8, 5: 8, 6: 16}.get(n, 0)


def cumulative_direct(n: int) -> int:
    """S(n) by summation in O(n)."""
    return sum(good_manifold_count(k) for k in range(n + 1))


def cumulative_closed(n: int) -> int:
    """S(n) in O(1) for n >= 6 via the closed form 2^(n+1)+43; else direct."""
    if n >= 6:
        return (1 << (n + 1)) + 43
    return cumulative_direct(n)


def divisibility_witness(n: int) -> Tuple[int, int, bool]:
    """Return (S(n), S(n) mod 128, divisible-by-128?)."""
    s = cumulative_closed(n)
    return s, s % 128, (s % 128 == 0)
